use std::{collections::HashMap, fs, io::{Read, Write}, path::{Path, PathBuf}, sync::Mutex, time::Duration};
use rusqlite::{params, Connection};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};

pub type MetadataResult<T> = Result<T, String>;
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)] #[serde(rename_all="camelCase")]
pub enum MetadataStatus { NotConfigured, Configured }
#[derive(Clone,Copy,Debug,PartialEq,Eq,Serialize)] #[serde(rename_all="camelCase")]
pub enum IntegrationState { NotConfigured, Connected, Error, Unavailable }
#[derive(Clone,Debug,Serialize)] #[serde(rename_all="camelCase")]
pub struct IntegrationStatus { pub id:String, pub state:IntegrationState, pub detail:String }
pub fn classify_connection_status(status:reqwest::StatusCode)->IntegrationStatus { let (state,detail)=if status.is_success(){(IntegrationState::Connected,"SteamGridDB conectado.".into())}else if status==reqwest::StatusCode::UNAUTHORIZED{(IntegrationState::Error,"A chave SteamGridDB foi recusada.".into())}else if status==reqwest::StatusCode::TOO_MANY_REQUESTS{(IntegrationState::Error,"SteamGridDB limitou temporariamente as solicitações.".into())}else{(IntegrationState::Error,format!("SteamGridDB respondeu {}.",status.as_u16()))}; IntegrationStatus{id:"steamgriddb".into(),state,detail} }
pub fn integration_status(store:&impl SecretStore)->Vec<IntegrationStatus>{ let steam=match metadata_status(store){MetadataStatus::Configured=>IntegrationStatus{id:"steamgriddb".into(),state:IntegrationState::NotConfigured,detail:"Chave salva. Use testar conexão para validar o serviço.".into()},MetadataStatus::NotConfigured=>IntegrationStatus{id:"steamgriddb".into(),state:IntegrationState::NotConfigured,detail:"Adicione uma chave para pesquisar artes.".into()}}; let retro=match retroachievements_status(store){MetadataStatus::Configured=>IntegrationStatus{id:"retroachievements".into(),state:IntegrationState::NotConfigured,detail:"Credenciais salvas. Teste a conexão para ativar o perfil.".into()},MetadataStatus::NotConfigured=>IntegrationStatus{id:"retroachievements".into(),state:IntegrationState::NotConfigured,detail:"Conecte seu usuário e chave de API para usar RetroAchievements.".into()}}; vec![IntegrationStatus{id:"steam".into(),state:IntegrationState::Connected,detail:"Biblioteca local pode ser sincronizada na tela Biblioteca.".into()},steam,IntegrationStatus{id:"screenscraper".into(),state:IntegrationState::Unavailable,detail:"Credenciais e adaptador ScreenScraper ainda não foram configurados.".into()},retro] }
pub trait SecretStore { fn read(&self, key:&str)->MetadataResult<Option<String>>; fn write(&self,key:&str,value:&str)->MetadataResult<()>; }
#[derive(Default)] pub struct MemorySecretStore(pub Mutex<HashMap<String,String>>);
impl SecretStore for MemorySecretStore { fn read(&self,key:&str)->MetadataResult<Option<String>> { Ok(self.0.lock().map_err(|_|"secret store unavailable".to_string())?.get(key).cloned()) } fn write(&self,key:&str,value:&str)->MetadataResult<()> { self.0.lock().map_err(|_|"secret store unavailable".to_string())?.insert(key.into(),value.into()); Ok(()) } }
pub struct WindowsCredentialStore;
impl WindowsCredentialStore { pub const SERVICE:&'static str="com.yoshima22.baconconsole"; }
impl SecretStore for WindowsCredentialStore { fn read(&self,key:&str)->MetadataResult<Option<String>> { let entry=keyring::Entry::new(Self::SERVICE,key).map_err(|e|e.to_string())?; match entry.get_password() { Ok(value)=>Ok(Some(value)), Err(keyring::Error::NoEntry)=>Ok(None), Err(error)=>Err(error.to_string()) } } fn write(&self,key:&str,value:&str)->MetadataResult<()> { keyring::Entry::new(Self::SERVICE,key).map_err(|e|e.to_string())?.set_password(value).map_err(|e|e.to_string()) } }
pub fn metadata_status(store:&impl SecretStore)->MetadataStatus { match store.read("steamgriddb-api-key") { Ok(Some(value)) if !value.trim().is_empty()=>MetadataStatus::Configured, _=>MetadataStatus::NotConfigured } }
pub fn retroachievements_status(store:&impl SecretStore)->MetadataStatus { match (store.read("retroachievements-user"),store.read("retroachievements-api-key")){(Ok(Some(user)),Ok(Some(key))) if !user.trim().is_empty()&&!key.trim().is_empty()=>MetadataStatus::Configured,_=>MetadataStatus::NotConfigured} }
pub struct RetroAchievementsProvider { user:String, api_key:String, client:reqwest::blocking::Client }
impl RetroAchievementsProvider { pub fn new(user:String,api_key:String)->MetadataResult<Self>{if user.trim().is_empty()||api_key.trim().len()<8{return Err("credenciais RetroAchievements inválidas".into())}let client=reqwest::blocking::Client::builder().timeout(Duration::from_secs(15)).redirect(reqwest::redirect::Policy::none()).build().map_err(|e|e.to_string())?;Ok(Self{user,api_key,client})} pub fn connection_status(&self)->MetadataResult<IntegrationStatus>{let mut url=url::Url::parse("https://retroachievements.org/API/API_GetUserProfile.php").map_err(|e|e.to_string())?;url.query_pairs_mut().append_pair("z",&self.user).append_pair("y",&self.api_key);let response=self.client.get(url).send().map_err(|_|"Não foi possível conectar ao RetroAchievements.".to_string())?;if response.status().is_success(){Ok(IntegrationStatus{id:"retroachievements".into(),state:IntegrationState::Connected,detail:format!("RetroAchievements conectado como {}.",self.user)})}else if response.status()==reqwest::StatusCode::UNAUTHORIZED||response.status()==reqwest::StatusCode::FORBIDDEN{Ok(IntegrationStatus{id:"retroachievements".into(),state:IntegrationState::Error,detail:"As credenciais RetroAchievements foram recusadas.".into()})}else{Ok(IntegrationStatus{id:"retroachievements".into(),state:IntegrationState::Error,detail:format!("RetroAchievements respondeu {}.",response.status().as_u16())})}} }
#[derive(Clone,Copy,Debug,PartialEq,Eq)] pub enum ArtworkKind { Cover, Background, Logo }
impl ArtworkKind { fn as_str(self)->&'static str { match self { Self::Cover=>"cover",Self::Background=>"background",Self::Logo=>"logo" } } pub fn from_str(value:&str)->MetadataResult<Self>{match value {"cover"=>Ok(Self::Cover),"background"=>Ok(Self::Background),"logo"=>Ok(Self::Logo),_=>Err("tipo de arte inválido".into())}} }
#[derive(Clone,Debug,Serialize)] #[serde(rename_all="camelCase")]
pub struct ArtworkRecord { pub provider:String,pub remote_id:i64,pub kind:String,pub original_url:String,pub local_path:String,pub mime:String,pub hash:String }
impl ArtworkRecord { pub fn new(provider:impl Into<String>,remote_id:i64,kind:ArtworkKind,original_url:impl Into<String>,local_path:impl Into<String>,mime:impl Into<String>,hash:impl Into<String>)->Self { Self { provider:provider.into(),remote_id,kind:kind.as_str().into(),original_url:original_url.into(),local_path:local_path.into(),mime:mime.into(),hash:hash.into() } } }
pub struct MetadataStore { db:PathBuf }
impl MetadataStore { pub fn open(root:&Path)->MetadataResult<Self> { fs::create_dir_all(root).map_err(|e|e.to_string())?; let store=Self{db:root.join("baconconsole.sqlite3")}; let conn=store.connection()?; conn.execute_batch("CREATE TABLE IF NOT EXISTS artwork_selections(game_id INTEGER NOT NULL, provider TEXT NOT NULL, remote_id INTEGER NOT NULL, kind TEXT NOT NULL, original_url TEXT NOT NULL, local_path TEXT NOT NULL, mime TEXT NOT NULL, hash TEXT NOT NULL, PRIMARY KEY(game_id,kind));").map_err(|e|e.to_string())?; Ok(store) } fn connection(&self)->MetadataResult<Connection>{Connection::open(&self.db).map_err(|e|e.to_string())} pub fn save_selected_artwork(&self,game_id:i64,record:&ArtworkRecord)->MetadataResult<()> { self.connection()?.execute("INSERT INTO artwork_selections(game_id,provider,remote_id,kind,original_url,local_path,mime,hash) VALUES(?1,?2,?3,?4,?5,?6,?7,?8) ON CONFLICT(game_id,kind) DO UPDATE SET provider=excluded.provider,remote_id=excluded.remote_id,original_url=excluded.original_url,local_path=excluded.local_path,mime=excluded.mime,hash=excluded.hash",params![game_id,record.provider,record.remote_id,record.kind,record.original_url,record.local_path,record.mime,record.hash]).map_err(|e|e.to_string())?; Ok(()) } pub fn selected_artwork(&self,game_id:i64,kind:ArtworkKind)->MetadataResult<Option<ArtworkRecord>> { let conn=self.connection()?; let result=conn.query_row("SELECT provider,remote_id,kind,original_url,local_path,mime,hash FROM artwork_selections WHERE game_id=?1 AND kind=?2",params![game_id,kind.as_str()],|row|Ok(ArtworkRecord{provider:row.get(0)?,remote_id:row.get(1)?,kind:row.get(2)?,original_url:row.get(3)?,local_path:row.get(4)?,mime:row.get(5)?,hash:row.get(6)?})); match result { Ok(record)=>Ok(Some(record)),Err(rusqlite::Error::QueryReturnedNoRows)=>Ok(None),Err(error)=>Err(error.to_string()) } } }
impl MetadataStore { pub fn all_selected_artwork(&self,game_id:i64)->MetadataResult<Vec<ArtworkRecord>> { let conn=self.connection()?;let mut statement=conn.prepare("SELECT provider,remote_id,kind,original_url,local_path,mime,hash FROM artwork_selections WHERE game_id=?1").map_err(|e|e.to_string())?;let rows=statement.query_map(params![game_id],|row|Ok(ArtworkRecord{provider:row.get(0)?,remote_id:row.get(1)?,kind:row.get(2)?,original_url:row.get(3)?,local_path:row.get(4)?,mime:row.get(5)?,hash:row.get(6)?})).map_err(|e|e.to_string())?;let records=rows.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;Ok(records) } }

pub const MAX_ARTWORK_BYTES:usize=16*1024*1024;
pub fn read_artwork_limited(reader:impl Read)->MetadataResult<Vec<u8>> { let mut bytes=Vec::new(); reader.take((MAX_ARTWORK_BYTES+1) as u64).read_to_end(&mut bytes).map_err(|_|"não foi possível ler a arte".to_string())?; if bytes.len()>MAX_ARTWORK_BYTES { return Err("arte excede o limite de tamanho".into()) } Ok(bytes) }
#[derive(Clone,Debug,Serialize,Deserialize)] #[serde(rename_all="camelCase")] pub struct MetadataCandidate { pub id:i64,pub name:String }
pub trait MetadataProvider { fn search(&self, title:&str)->MetadataResult<Vec<MetadataCandidate>>; }
pub struct SteamGridDbProvider { api_key:String, client:reqwest::blocking::Client }
#[derive(Clone,Debug,Serialize,Deserialize)] #[serde(rename_all="camelCase")] pub struct ArtworkOption { pub id:i64,pub url:String, #[serde(default)] pub thumb:String }
impl SteamGridDbProvider { pub fn new(api_key:String)->MetadataResult<Self>{ if api_key.trim().is_empty(){return Err("SteamGridDB não configurado".into())} let client=reqwest::blocking::Client::builder().timeout(Duration::from_secs(15)).redirect(reqwest::redirect::Policy::none()).build().map_err(|e|e.to_string())?; Ok(Self{api_key,client}) } pub fn connection_status(&self)->MetadataResult<IntegrationStatus>{let url="https://www.steamgriddb.com/api/v2/search/autocomplete/baconconsole";let response=self.client.get(url).header(reqwest::header::AUTHORIZATION,format!("Bearer {}",self.api_key)).send().map_err(|_|"Não foi possível conectar ao SteamGridDB.".to_string())?;Ok(classify_connection_status(response.status()))} pub fn parse_search_response(body:&str)->MetadataResult<Vec<MetadataCandidate>> { #[derive(Deserialize)] struct Response { success:bool,data:Vec<MetadataCandidate> } let response:Response=serde_json::from_str(body).map_err(|_|"resposta de metadados inválida".to_string())?; if !response.success{return Err("SteamGridDB recusou a busca".into())} Ok(response.data.into_iter().take(20).collect()) } pub fn fetch_artwork(&self,cache:&ArtworkCache,url:&str)->MetadataResult<CachedArtwork>{ validate_artwork_url(url)?; let response=self.client.get(url).send().map_err(|_|"não foi possível baixar a arte".to_string())?; if !response.status().is_success(){return Err(format!("download de arte falhou ({})",response.status()))} if let Some(size)=response.content_length(){if size as usize>MAX_ARTWORK_BYTES{return Err("arte excede o limite de tamanho".into())}} let mime=response.headers().get(reqwest::header::CONTENT_TYPE).and_then(|value|value.to_str().ok()).unwrap_or("").split(';').next().unwrap_or("").to_owned(); let bytes=read_artwork_limited(response)?; cache.store(url,&mime,&bytes) } }
impl MetadataProvider for SteamGridDbProvider { fn search(&self,title:&str)->MetadataResult<Vec<MetadataCandidate>> { let encoded:url::Url=url::Url::parse("https://www.steamgriddb.com/api/v2/").map_err(|e|e.to_string())?.join(&format!("search/autocomplete/{}",url::form_urlencoded::byte_serialize(title.as_bytes()).collect::<String>())).map_err(|e|e.to_string())?; let response=self.client.get(encoded).header(reqwest::header::AUTHORIZATION,format!("Bearer {}",self.api_key)).send().map_err(|_|"não foi possível consultar SteamGridDB".to_string())?; if response.status()==reqwest::StatusCode::UNAUTHORIZED{return Err("chave SteamGridDB inválida".into())} if !response.status().is_success(){return Err(format!("SteamGridDB respondeu {}",response.status()))} Self::parse_search_response(&response.text().map_err(|_|"resposta SteamGridDB inválida".to_string())?) } }
impl SteamGridDbProvider { pub fn parse_artwork_response(body:&str)->MetadataResult<Vec<ArtworkOption>> { #[derive(Deserialize)] struct Response { success:bool,data:Vec<ArtworkOption> } let response:Response=serde_json::from_str(body).map_err(|_|"resposta de arte inválida".to_string())?; if !response.success{return Err("SteamGridDB recusou as artes".into())} Ok(response.data.into_iter().filter(|option|validate_artwork_url(&option.url).is_ok()).take(20).collect()) } pub fn artwork_options(&self,game_id:i64,kind:ArtworkKind)->MetadataResult<Vec<ArtworkOption>> { let route=match kind { ArtworkKind::Cover=>format!("grids/game/{game_id}?dimensions=600x900&types=static&nsfw=false&limit=20"),ArtworkKind::Background=>format!("heroes/game/{game_id}?types=static&nsfw=false&limit=20"),ArtworkKind::Logo=>format!("logos/game/{game_id}?types=static&nsfw=false&limit=20")}; let url=url::Url::parse("https://www.steamgriddb.com/api/v2/").map_err(|e|e.to_string())?.join(&route).map_err(|e|e.to_string())?; let response=self.client.get(url).header(reqwest::header::AUTHORIZATION,format!("Bearer {}",self.api_key)).send().map_err(|_|"não foi possível consultar SteamGridDB".to_string())?; if !response.status().is_success(){return Err(format!("SteamGridDB respondeu {}",response.status()))} Self::parse_artwork_response(&response.text().map_err(|_|"resposta SteamGridDB inválida".to_string())?) } }
pub struct ScreenScraperProvider;
impl MetadataProvider for ScreenScraperProvider { fn search(&self,_:&str)->MetadataResult<Vec<MetadataCandidate>> { Err("ScreenScraper não configurado".into()) } }
pub fn validate_artwork_url(value:&str)->MetadataResult<url::Url>{let url=url::Url::parse(value).map_err(|_|"URL de arte inválida".to_string())?; let host=url.host_str().ok_or("URL de arte sem host")?.to_ascii_lowercase(); if url.scheme()!="https" || !(host=="cdn.steamgriddb.com" || host=="steamgriddb.com" || host.ends_with(".steamgriddb.com")){return Err("origem de arte não permitida".into())} Ok(url)}
#[derive(Clone,Debug,Serialize)] #[serde(rename_all="camelCase")] pub struct CachedArtwork { pub local_path:String,pub mime:String,pub hash:String }
pub struct ArtworkCache { root:PathBuf }
impl ArtworkCache { pub fn new(root:&Path)->MetadataResult<Self>{let root=root.join("artwork");fs::create_dir_all(&root).map_err(|e|e.to_string())?;Ok(Self{root})} pub fn store(&self,url:&str,mime:&str,bytes:&[u8])->MetadataResult<CachedArtwork>{validate_artwork_url(url)?; let extension=match mime {"image/png"=>"png","image/jpeg"=>"jpg","image/webp"=>"webp",_=>return Err("tipo de arte não permitido".into())}; if bytes.len()>MAX_ARTWORK_BYTES{return Err("arte excede o limite de tamanho".into())} let hash=format!("{:x}",Sha256::digest(bytes)); let name=format!("{hash}.{extension}");let destination=self.root.join(&name);if !destination.exists(){let temporary=self.root.join(format!("{name}.part"));let mut file=fs::File::create(&temporary).map_err(|e|e.to_string())?;file.write_all(bytes).map_err(|e|e.to_string())?;file.sync_all().map_err(|e|e.to_string())?;fs::rename(temporary,&destination).map_err(|e|e.to_string())?;}Ok(CachedArtwork{local_path:format!("artwork/{name}"),mime:mime.into(),hash})} }
